const elmerFollowupMarker='<!--ELMER_FOLLOWUPS-->';
function clearElmerFollowups(){followupGeneration+=1;followups.classList.remove('visible');followupList.textContent=''}
function parseElmerFollowups(text){let items=[];const raw=String(text||'').trim(),json=raw.match(/\[[\s\S]*\]/);if(json){try{const parsed=JSON.parse(json[0]);if(Array.isArray(parsed))items=parsed}catch(error){}}if(!items.length)items=raw.split(/\r?\n/).map(line=>line.replace(/^\s*(?:[-*•]|\d+[.)])\s*/,''));const seen=new Set();return items.map(item=>String(item||'').trim().replace(/^['\"]|['\"]$/g,'')).filter(item=>item&&item.length<=180&&!/^(?:related|follow[- ]?up|references?)\b/i.test(item)).map(item=>/[?？]$/.test(item)?item:item+'?').filter(item=>{const key=item.toLocaleLowerCase();if(seen.has(key))return false;seen.add(key);return true}).slice(0,3)}
function splitElmerResponse(text){const value=String(text||''),index=value.indexOf(elmerFollowupMarker);return index<0?{answer:value,followups:''}:{answer:value.slice(0,index).trimEnd(),followups:value.slice(index+elmerFollowupMarker.length)}}
