const blobDataUrl=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('The browser could not read that image.'));reader.readAsDataURL(blob)});
async function compressedElmerImage(canvas){let blob=null;for(const quality of [.92,.82,.72,.62,.52]){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=550*1024)return blob}throw new Error('The prepared image is too large. Crop it and try again.')}
async function attachElmerImage(file){
  if(!file)return;
  if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Attach a PNG, JPEG, or WebP image.');
  if(file.size>12*1024*1024)throw new Error('That image is too large. Choose an image smaller than 12 MB.');
  const source=await blobDataUrl(file),loaded=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('The browser could not open that image.'));img.src=source}),scale=Math.min(1,1600/Math.max(loaded.naturalWidth,loaded.naturalHeight)),width=Math.max(1,Math.round(loaded.naturalWidth*scale)),height=Math.max(1,Math.round(loaded.naturalHeight*scale)),canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;canvas.getContext('2d',{alpha:false}).drawImage(loaded,0,0,width,height);const cleanBlob=await compressedElmerImage(canvas),cleanUrl=await blobDataUrl(cleanBlob);attachedImage={media_type:'image/jpeg',data_base64:cleanUrl.split(',',2)[1]};imageThumb.src=cleanUrl;imageMeta.textContent=`${file.name||'Pasted screenshot'} · ${width} × ${height} · ${Math.max(1,Math.round(cleanBlob.size/1024)).toLocaleString()} KB`;imagePreview.classList.add('visible')
}
imageInput.addEventListener('change',async()=>{try{await attachElmerImage(imageInput.files?.[0])}catch(error){clearAttachedImage();window.alert(error.message)}});imageRemove.addEventListener('click',clearAttachedImage);
question.addEventListener('paste',event=>{const item=[...(event.clipboardData?.items||[])].find(entry=>entry.kind==='file'&&entry.type.startsWith('image/'));if(!item)return;attachElmerImage(item.getAsFile()).catch(error=>{clearAttachedImage();window.alert(error.message)})});
// File drops share the existing image validation and preview flow.
let elmerDragDepth = 0;
const isElmerFileDrag = event => Array.from(event.dataTransfer?.types || []).includes('Files');
const resetElmerDrop = () => { elmerDragDepth = 0; form.classList.remove('elmer-image-dragover'); };
form.addEventListener('dragenter', event => {
  if (!isElmerFileDrag(event)) return;
  event.preventDefault();
  elmerDragDepth++;
  form.classList.add('elmer-image-dragover');
});
form.addEventListener('dragover', event => {
  if (!isElmerFileDrag(event)) return;
  event.preventDefault();
  event.dataTransfer.dropEffect = 'copy';
});
form.addEventListener('dragleave', event => {
  if (elmerDragDepth > 0) elmerDragDepth--;
  if (!elmerDragDepth) resetElmerDrop();
});
form.addEventListener('drop', async event => {
  if (!isElmerFileDrag(event)) return;
  event.preventDefault();
  resetElmerDrop();
  const files = Array.from(event.dataTransfer.files || []);
  if (files.length !== 1) { window.alert('Drop one PNG, JPEG, or WebP image at a time.'); return; }
  try { await attachElmerImage(files[0]); }
  catch (error) { clearAttachedImage(); window.alert(error.message); }
});
