function cwShorthand(text){return String(text||'').replace(/[‘’]/g,"'").replace(/[–—]/g,'-').replace(/\byou're\b/gi,'U R').replace(/\byour\b/gi,'UR').replace(/\bhere\b/gi,'HT').replace(/\bare\b/gi,'R').replace(/\byou\b/gi,'U')}
