  const activity=clean.match(/^tune(?:\s+(?:radio|receiver)\s*([1-4]))?\s+to\s+(ft\s*-?\s*8|ft\s*-?\s*4)\s+(?:on|for|in)\s+(?:the\s+)?(160|80|60|40|30|20|17|15|12|10|6|2)\s*(?:m|meters?|metres?)?(?:\s+band)?$/i);
