  const sections=['OH','MI','IL','IN','WNY','ENY','EPA','MDC','NC','SC','GA','NFL','STX','NTX','CO','AZ','ORG','WWA','EB','SV','LAX','PAC','AK','ONN','ONS','QC','MAR'],precedence=['A','A','A','B','Q','U','M','S'],prefixes=['W1','K1','N1','W2','K2','N2','W3','K3','N3','W4','K4','N4','W5','K5','N5','W6','K6','N6','W7','K7','N7','W8','K8','N8','W9','K9','N9','W0','K0','N0','VE2','VE3','VE4','VE5','VE6','VE7','VA2','VA3'],letters='ABCDEFGHIJKLMNOPQRSTUVWXYZ',exchanges=[],ssCall=()=>{let suffix='';for(let i=0;i<(Math.random()<.28?2:3);i++)suffix+=letters[Math.floor(Math.random()*letters.length)];return prefixes[Math.floor(Math.random()*prefixes.length)]+suffix};
  for(let index=0;index<5;index++){const call=ssCall(),serial=String(1+Math.floor(Math.random()*899)),prec=precedence[Math.floor(Math.random()*precedence.length)],check=String(40+Math.floor(Math.random()*59)).padStart(2,'0'),section=sections[Math.floor(Math.random()*sections.length)],lead=Math.random()<.5?`${rigPiCall||'W6HN'} DE ${call}`:`${call}`;exchanges.push({label:`Sweepstakes contact ${index+1}`,text:`${lead} ${serial} ${prec} ${call} ${check} ${section} K`})}
