}
function randomCallForPrefix(prefix){const letters='ABCDEFGHIJKLMNOPQRSTUVWXYZ';let suffix='';for(let i=0;i<(Math.random()<.28?2:3);i++)suffix+=letters[Math.floor(Math.random()*letters.length)];return prefix+suffix}
function randomGroupsPractice(){const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',exchanges=[];for(let round=0;round<10;round++){const groups=[];for(let group=0;group<5;group++){let value='';for(let character=0;character<5;character++)value+=alphabet[Math.floor(Math.random()*alphabet.length)];groups.push(value)}exchanges.push({label:`Five-character groups ${round+1}`,text:groups.join(' ')})}return {remote:'GROUPS',exchanges}}
function randomCqwwPractice(){const profiles=[['W1',5],['W6',3],['VE3',4],['G4',14],['DL1',14],['SM5',14],['JA1',25],['VK2',30],['ZS6',38],['F4',14],['EA7',14],['PY2',11],['LU2',13],['YB1',28],['9A1',15]],exchanges=[];for(let index=0;index<5;index++){const profile=profiles[Math.floor(Math.random()*profiles.length)],call=randomCallForPrefix(profile[0]),lead=Math.random()<.5?`${rigPiCall||'W6HN'} DE ${call}`:call;exchanges.push({label:`CQ WW contact ${index+1}`,text:`${lead} 5NN ${profile[1]} ${profile[1]} TU`})}return {remote:'CQWW',exchanges}}
function randomWpxPractice(){const prefixes=['W1','K3','N5','W6','VE3','G4','DL1','SM5','JA1','VK2','ZS6','F4','EA7','PY2','LU2','YB1','9A1'],exchanges=[];for(let index=0;index<5;index++){const call=randomCallForPrefix(prefixes[Math.floor(Math.random()*prefixes.length)]),serial=String(1+Math.floor(Math.random()*999)),lead=Math.random()<.5?`${rigPiCall||'W6HN'} DE ${call}`:call;exchanges.push({label:`CQ WPX contact ${index+1}`,text:`${lead} 5NN ${serial} ${serial} TU`})}return {remote:'WPX',exchanges}}
function randomArrlDxPractice(){const myCall=String(rigPiCall||'W6HN').toUpperCase(),wve=/^(?:[AKNW][A-Z]?\d|V[AEYO]\d)/.test(myCall),dxPrefixes=['G4','DL1','SM5','JA1','VK2','ZS6','F4','EA7','PY2','LU2','YB1','9A1'],wveProfiles=[['W1','MA'],['K2','NY'],['N3','PA'],['W4','FL'],['K5','TX'],['W6','CA'],['K7','AZ'],['W8','OH'],['K9','IL'],['W0','CO'],['VE3','ON'],['VA2','QC'],['VE7','BC']],powers=['5','25','50','100','200','400','500','1000'],exchanges=[];for(let index=0;index<5;index++){let call,exchange;if(wve){call=randomCallForPrefix(dxPrefixes[Math.floor(Math.random()*dxPrefixes.length)]);exchange=powers[Math.floor(Math.random()*powers.length)]}else{const profile=wveProfiles[Math.floor(Math.random()*wveProfiles.length)];call=randomCallForPrefix(profile[0]);exchange=profile[1]}const lead=Math.random()<.5?`${myCall} DE ${call}`:call;exchanges.push({label:`ARRL International DX contact ${index+1}`,text:`${lead} 5NN ${exchange} ${exchange} TU`})}return {remote:'ARRLDX',exchanges}}
function randomFieldDayPractice(){const profiles=[['W1','CT'],['K2','NNJ'],['N3','EPA'],['W4','GA'],['K5','NTX'],['W6','SCV'],['K7','AZ'],['W8','OH'],['K9','IL'],['W0','CO'],['VE2','QC'],['VE3','ONE'],['VE7','BC']],classes=['1A','2A','3A','4A','1B','1C','1D','1E','1F'],exchanges=[];for(let index=0;index<5;index++){const profile=profiles[Math.floor(Math.random()*profiles.length)],call=randomCallForPrefix(profile[0]),stationClass=classes[Math.floor(Math.random()*classes.length)],lead=Math.random()<.5?`${rigPiCall||'W6HN'} DE ${call}`:call;exchanges.push({label:`Field Day contact ${index+1}`,text:`${lead} ${stationClass} ${profile[1]} ${stationClass} ${profile[1]} TU`})}return {remote:'FD',exchanges}}
function practiceSequenceForMode(mode){return mode==='pileup'?randomPileupPractice():mode==='sweepstakes'?randomSweepstakesPractice():mode==='groups'?randomGroupsPractice():mode==='cqww'?randomCqwwPractice():mode==='wpx'?randomWpxPractice():mode==='arrldx'?randomArrlDxPractice():mode==='fieldday'?randomFieldDayPractice():randomPracticeQso()}
function nextCodePracticeCall(){if(!elmerCodeState)return;const state=elmerCodeState;if(state.mode!=='callsign'){state.step++;if(state.step>=state.qso.exchanges.length){state.qso=practiceSequenceForMode(state.mode);state.step=0}state.target=state.qso.exchanges[state.step].text}else{let target;do target=randomPracticeCall();while(target===state.target);state.target=target}state.checked=false;state.played=false;renderCodePractice()}
function schedulePracticeMorse(context,destination,text,options={}){const oscillator=context.createOscillator(),gain=context.createGain(),wpm=options.wpm||15,effective=Math.min(options.effective||wpm,wpm),dot=1.2/wpm,gapScale=wpm/effective,level=options.level||.16;oscillator.type='sine';oscillator.frequency.value=options.frequency||650;gain.gain.value=0;oscillator.connect(gain).connect(destination);let t=context.currentTime+(options.delay??.06);for(let c=0;c<text.length;c++){const code=elmerMorse[text[c]]||'';if(!code){t+=7*dot*gapScale;continue}for(let s=0;s<code.length;s++){const duration=(code[s]==='-'?3:1)*dot;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(level,t+.004);gain.gain.setValueAtTime(level,t+Math.max(.004,duration-.005));gain.gain.linearRampToValueAtTime(0,t+duration);t+=duration;if(s<code.length-1)t+=dot}if(c<text.length-1)t+=3*dot*gapScale}oscillator.start();oscillator.stop(t+.08);return t}
