function loadPracticeNoiseBytes(){if(!elmerNoiseBytesPromise)elmerNoiseBytesPromise=fetch('/Recordings/noise.mp3',{cache:'force-cache'}).then(response=>response.ok?response.arrayBuffer():null).catch(()=>null);return elmerNoiseBytesPromise}
function addPracticeNoiseRecording(context,destination,buffer,level,stopAt){if(!buffer||!buffer.duration||!level)return;const source=context.createBufferSource(),gain=context.createGain(),offset=Math.random()*Math.max(.01,buffer.duration-1);source.buffer=buffer;source.loop=true;gain.gain.value=level;source.connect(gain).connect(destination);source.start(context.currentTime,offset);source.stop(stopAt)}
