    schedulePracticeMorse(context,master,qrmText.repeat(8),{wpm:Math.min(40,state.wpm+5),effective:Math.min(40,state.wpm+5),frequency:state.conditions==='busy'?735:545,level:state.conditions==='busy'?.07:.042,delay:.35+Math.random()*.8});
