:data.license_class,figures_only:data.figures_only===true}));const source=document.createElement('div');source.className='elmer-exam-source';source.append(document.createTextNode(`${data.pool_title} · `));const link=document.createElement('a');link.href=data.source_url;link.target='_blank';link.rel='noopener';link.textContent='Official NCVEC pool';source.append(link);if(data.fcc_reference)source.append(document.createTextNode(` · ${data.fcc_reference}`));card.append(head,topic,prompt,choices,resultBox,actions,source);if(figure)prompt.before(figure);answer.append(card);metrics.textContent=`Official current pool · ${data.notice}`}
async function loadExamQuestion(request){button.disabled=true;pendingExamExplanation=null;currentExamResult=null;pendingExamImage=null;resetForExamCard();statusBox.textContent=`Choosing a ${examClassLabel(request.license_class)} question…`;try{const response=await fetch('/programs/ElmerExamQuestion.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(request)}),data=await response.json().catch(()=>({}));if(response.status===401||response.status===403){location.href='/login.php';return}if(!response.ok)throw new Error(data.error||'RigPi could not retrieve an exam question.');renderExamQuestion(data)}catch(error){statusBox.textContent='Elmer could not open study mode.';answer.textContent=error.message}finally{button.disabled=false;question.focus()}}
function launchExamConfetti(){const layer=document.createElement('div');layer.className='elmer-confetti';const colors=['#176b99','#f2c14e','#27834c','#d7263d','#7a4eb3','#f48c06'];for(let i=0;i<90;i++){const piece=document.createElement('i');piece.className='elmer-confetti-piece';piece.style.background=colors[i%colors.length];piece.style.setProperty('--x',`${Math.round((Math.random()-.5)*1100)}px`);piece.style.setProperty('--y',`${Math.round(260+Math.random()*520)}px`);piece.style.setProperty('--r',`${Math.round((Math.random()-.5)*1500)}deg`);piece.style.animationDelay=`${Math.random()*.18}s`;layer.append(piece)}document.body.append(layer);setTimeout(()=>layer.remove(),2900)}
function renderFullExamQuestion(){if(!activeFullExam)return;resetForExamCard();const state=activeFullExam,data=state.data,q=data.questions[state.index],answered=Object.keys(state.answers).length,card=document.createElement('section');card.className='elmer-full-exam';const bar=document.createElement('div');bar.className='elmer-full-exam-bar';const heading=document.createElement('span');heading.className='elmer-exam-class';heading.textContent=`${examClassLabel(data.license_class)} simulated exam`;const progress=document.createElement('span');progress.className='elmer-full-exam-progress';progress.textContent=`Question ${state.index+1} of ${data.question_count} · ${answered} answered`;bar.append(heading,progress);const palette=document.createElement('div');palette.className='elmer-exam-palette';data.questions.forEach((item,index)=>{const jump=document.createElement('button');jump.type='button';jump.className='elmer-exam-number';if(state.answers[index])jump.classList.add('answered');if(index===state.index)jump.classList.add('current');jump.textContent=String(index+1);jump.title=item.question_id;jump.addEventListener('click',()=>{state.index=index;renderFullExamQuestion()});palette.append(jump)});const head=document.createElement('div');head.className='elmer-exam-head';const topic=document.createElement('span');topic.className='elmer-exam-topic';topic.textContent=q.topic||q.group;const id=document.createElement('span');id.className='elmer-exam-id';id.textContent=q.question_id;head.append(topic,id);let figure=null;if(q.figure_url){figure=document.createElement('figure');figure.className='elmer-exam-figure';const link=document.createElement('a');link.href=q.figure_url;link.target='_blank';link.rel='noopener';const image=document.createElement('img');image.src=q.figure_url;image.alt=q.figure_label||'Official exam figure';link.append(image);const caption=document.createElement('figcaption');caption.textContent=`${q.figure_label} · Select the image to enlarge`;figure.append(link,caption)}const prompt=document.createElement('p');prompt.className='elmer-exam-question';prompt.textContent=q.question;const choices=document.createElement('div');choices.className='elmer-exam-choices';['A','B','C','D'].forEach((letter,index)=>{const choice=document.createElement('button');choice.type='button';choice.className='elmer-exam-choice';if(state.answers[state.index]===letter)choice.classList.add('selected');const marker=document.createElement('span');marker.className='elmer-exam-letter';marker.textContent=`${letter}.`;const wording=document.createElement('span');wording.textContent=q.choices[index];choice.append(marker,wording);choice.addEventListener('click',()=>{state.answers[state.index]=letter;renderFullExamQuestion()});choices.append(choice)});const nav=document.createElement('div');nav.className='elmer-full-exam-nav';const move=document.createElement('div');move.className='elmer-full-exam-nav-group';const previous=document.createElement('button');previous.type='button';previous.className='btn btn-outline-primary btn-sm';previous.textContent='Previous';previous.disabled=state.index===0;previous.addEventListener('click',()=>{state.index--;renderFullExamQuestion()});const next=document.createElement('button');next.type='button';next.className='btn btn-primary btn-sm';next.textContent='Next';next.disabled=state.index===data.question_count-1;next.addEventListener('click',()=>{state.index++;renderFullExamQuestion()});move.append(previous,next);const finish=document.createElement('button');finish.type='button';finish.className='btn btn-success btn-sm';finish.textContent='Finish exam';finish.addEventListener('click',()=>finishFullExam());nav.append(move,finish);card.append(bar,palette,head);if(figure)card.append(figure);card.append(prompt,choices,nav);answer.append(card);metrics.textContent=`Answers are hidden until you finish · Passing score: ${data.passing_score} of ${data.question_count}`}
function reviewFullExamQuestion(index){const state=activeFullExam;if(!state)return;const q=state.data.questions[index],selected=state.answers[index]||'';renderExamQuestion(q);if(selected){const choice=answer.querySelector(`.elmer-exam-choice[data-letter="${selected}"]`);if(choice)choice.click()}const card=answer.querySelector('.elmer-exam'),back=document.createElement('button');back.type='button';back.className='btn btn-outline-primary btn-sm';back.textContent='Back to exam results';back.addEventListener('click',()=>finishFullExam(true));const actions=card&&card.querySelector('.elmer-exam-actions');if(actions){actions.append(back);actions.hidden=false}else if(card)card.append(back)}
function finishFullExam(skipConfirm=false){if(!activeFullExam)return;const state=activeFullExam,data=state.data,unanswered=data.question_count-Object.keys(state.answers).length;if(!skipConfirm){const message=unanswered?`Finish with ${unanswered} unanswered question${unanswered===1?'':'s'}?`:'Finish and score this exam?';if(!window.confirm(message))return}const correct=data.questions.reduce((total,q,index)=>total+(state.answers[index]===q.correct_letter?1:0),0),passed=correct>=data.passing_score,percent=Math.round(correct/data.question_count*100),missed=data.questions.map((q,index)=>({q,index,selected:state.answers[index]||''})).filter(item=>item.selected!==item.q.correct_letter);resetForExamCard();const card=document.createElement('section');card.className='elmer-full-exam';const score=document.createElement('div');score.className=`elmer-exam-score ${passed?'pass':'fail'}`;const title=document.createElement('h2');title.textContent=passed?'You passed!':'Keep studying';const number=document.createElement('div');number.className='elmer-exam-score-number';number.textContent=`${correct} / ${data.question_count} · ${percent}%`;const detail=document.createElement('p');detail.textContent=passed?`Passing score: ${data.passing_score}. Congratulations!`:`Passing score: ${data.passing_score}. Review the missed questions and try again.`;score.append(title,number,detail);const actions=document.createElement('div');actions.className='elmer-exam-actions';const again=document.createElement('button');again.type='button';again.className='btn btn-primary';again.textContent=`Start another ${examClassLabel(data.license_class)} exam`;again.addEventListener('click',()=>loadFullExam({license_class:data.license_class,mode:'exam'}));actions.append(again);card.append(score,actions);if(missed.length){const reviewTitle=document.createElement('h3');reviewTitle.textContent=`Review missed${unanswered?' and unanswered':''} questions`;const review=document.createElement('div');review.className='elmer-exam-review';missed.forEach(item=>{const open=document.createElement('button');open.type='button';open.className='btn btn-outline-secondary btn-sm';open.textContent=`${item.index+1}. ${item.q.question_id}${item.selected?'':' · unanswered'}`;open.addEventListener('click',()=>reviewFullExamQuestion(item.index));review.append(open)});card.append(reviewTitle,review)}answer.append(card);lastQuestion=`${examClassLabel(data.license_class)} simulated exam`;lastAnswer=`Score: ${correct} of ${data.question_count} (${percent}%). ${passed?'Passed.':'Not passed.'}`;metrics.textContent=`Official current pool · ${correct} correct · ${missed.length-unanswered} incorrect · ${unanswered} unanswered`;if(passed&&!state.celebrated){state.celebrated=true;launchExamConfetti()}}
