function requestedFrequencyIntelligence(text){
    text=String(text||'');
    if(/\bcurrent\s+(?:frequency|mode)\b/i.test(text)&&!/[0-9]/.test(text))return null;

    const classMatch=text.match(/\b(amateur\s+extra|extra|advanced|general|technician|tech|novice)\b/i);
    let license_class='';

    if(classMatch){
        const c=classMatch[1].toLowerCase();
        license_class=
            c==='extra' || c==='amateur extra' ? 'Amateur Extra' :
            c==='tech' || c==='technician' ? 'Technician' :
            c==='general' ? 'General' :
            c==='advanced' ? 'Advanced' :
            c==='novice' ? 'Novice' : '';
    }

    const m=text.match(/\b(\d+(?:\.\d+)?)\s*(ghz|mhz|khz|hz)\b/i);

    if(m){
        const value=Number(m[1]);
        const unit=m[2].toLowerCase();
        const scale=
            unit==='ghz' ? 1e9 :
            unit==='mhz' ? 1e6 :
            unit==='khz' ? 1e3 : 1;

        const frequency_hz=Math.round(value*scale);

        if(Number.isFinite(frequency_hz) && frequency_hz>0){
            return license_class
                ? {frequency_hz,license_class}
                : {frequency_hz};
        }
    }

    const activityMatch=text.match(/\b(ft8|ft4|sstv|rtty|psk31|js8(?:call)?)\b/i);
    let activity_query='';

    if(activityMatch){
        const token=activityMatch[1].toLowerCase();
        activity_query=
            token==='js8call' ? 'JS8Call' :
            token==='js8' ? 'JS8' : token.toUpperCase();
    }

    const bandMatch=text.match(/\b(160|80|60|40|30|20|17|15|12|10|6|2|1\.25|70|33|23)\s*(cm|m|meters?|metres?)?\b/i);
    let band_query='';

    if(bandMatch){
        const value=bandMatch[1];
        const unit=String(bandMatch[2]||'').toLowerCase();
        band_query=unit==='cm' || (!unit&&['70','33','23'].includes(value))
            ? `${value}cm`
            : `${value}m`;
    }

    if(activity_query&&band_query){
        const request={query_mode:'activity_on_band',activity_query,band_query};
        if(license_class)request.license_class=license_class;
        return request;
    }

    const directoryIntent=/\b(?:what|which)\s+bands?\b|\bwhere\b|\bfind\b|\bactivity\s+(?:frequencies|ranges|bands)\b/i.test(text);

    if(activity_query&&directoryIntent){
        return {query_mode:'activity_directory',activity_query};
    }

    if(/\b(?:where am i tuned|what am i tuned to|current frequency|currently tuned|this frequency|at this frequency|operate here|activity here|what happens here|what is here)\b/i.test(text)){
        return license_class ? {license_class} : {};
    }

    return null;
}

const liveContextBeforeFrequency=liveContextFromPlan;

liveContextFromPlan=async function(plan,text){
    const context=await liveContextBeforeFrequency(plan,text);

    let request=requestedFrequencyIntelligence(
        String(plan?.english_search_query || '')
    );

    if(request===null){
        request=requestedFrequencyIntelligence(text);
    }

    if(request===null){
        return context;
    }

    statusBox.textContent=request.query_mode==='activity_directory'
        ? `Elmer is checking RigPi's ${request.activity_query} activity directory…`
        : request.query_mode==='activity_on_band'
            ? `Elmer is checking ${request.activity_query} on ${request.band_query} and license privileges…`
            : request.frequency_hz
                ? 'Elmer is checking the band plan and license privileges…'
                : 'Elmer is checking your current frequency and license privileges…';

    const response=await fetch('/programs/ElmerFrequency.php',{
        method:'POST',
        credentials:'same-origin',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify(request)
    });

    const data=await response.json().catch(()=>({}));

    if(response.status===401 || response.status===403){
        location.href='/login.php';
        throw new Error('Please sign in to RigPi.');
    }

    if(!response.ok){
        throw new Error(
            data.error ||
            'RigPi could not retrieve frequency intelligence.'
        );
    }

    return {
        ...(context||{}),
        frequency_intelligence:data
    };
};

function requestedPropagationGuidance(value){
    const text=String(value||'');
    if(!/\b(?:best|good|better|optimum|opening|open|work|reach|contact|propagation|time|when)\b/i.test(text))return null;
    const bandWords={
        'one sixty':160,'one hundred sixty':160,'eighty':80,'sixty':60,
        'forty':40,'thirty':30,'twenty':20,'seventeen':17,'fifteen':15,
        'twelve':12,'ten':10
    };
    let band=0;
    const numeric=text.match(/\b(160|80|60|40|30|20|17|15|12|10)\s*(?:m|meter|meters|metre|metres)\b/i);
    if(numeric)band=Number(numeric[1]);
    if(!band){
        const lower=text.toLowerCase();
        for(const [word,value] of Object.entries(bandWords)){
            if(new RegExp(`\\b${word}\\s*(?:m|meter|meters|metre|metres)?\\b`,'i').test(lower)){band=value;break;}
        }
    }
    const regions=[
        ['south_america',/\b(?:south america|latin america)\b/i],
        ['north_america',/\bnorth america\b/i],
        ['australia',/\baustralia\b/i],['oceania',/\boceania\b/i],
        ['caribbean',/\bcaribbean\b/i],['japan',/\bjapan\b/i],
        ['europe',/\beurope(?:an)?\b/i],['africa',/\bafrica(?:n)?\b/i],
        ['asia',/\basia(?:n)?\b/i]
    ];
    const target=regions.find(([,pattern])=>pattern.test(text));
    if(target)return {band_meters:band,target_region:target[0],target_query:'',day_offset:/\btomorrow\b/i.test(text)?1:0};
    const destinationPatterns=[
        /\b(?:work|reach|contact)\s+(?:with\s+)?(?:stations?\s+(?:in|near)\s+)?(.+?)(?=\s+(?:on|using|tomorrow|today|tonight|this|next|at|from|during)\b|[?.!,;]|$)/i,
        /\b(?:best|good|better|optimum)\s+time\s+(?:for|to\s+(?:work|reach|contact))\s+(.+?)(?=\s+(?:on|using|tomorrow|today|tonight|this|next|at|from|during)\b|[?.!,;]|$)/i,
        /\bpropagation\s+(?:to|for)\s+(.+?)(?=\s+(?:on|using|tomorrow|today|tonight|this|next|at|from|during)\b|[?.!,;]|$)/i
    ];
    let place='';
    for(const pattern of destinationPatterns){const match=text.match(pattern);if(match){place=String(match[1]||'').trim().replace(/^the\s+/i,'');break;}}
    if(place.length<2||place.length>100)return null;
    return {band_meters:band,target_region:'place',target_query:place,day_offset:/\btomorrow\b/i.test(text)?1:0};
}

const liveContextBeforePropagation=liveContextFromPlan;
liveContextFromPlan=async function(plan,text){
    const context=await liveContextBeforePropagation(plan,text);
    const request=requestedPropagationGuidance(text)||requestedPropagationGuidance(String(plan?.english_search_query||''));
    if(!request)return context;
    statusBox.textContent='Elmer is checking station-aware HF propagation guidance…';
    const response=await fetch('/programs/ElmerPropagation.php',{
        method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},
        body:JSON.stringify(request)
    });
    const data=await response.json().catch(()=>({}));
    if(response.status===401||response.status===403){location.href='/login.php';throw new Error('Please sign in to RigPi.');}
    if(!response.ok)throw new Error(data.error||'RigPi could not prepare propagation guidance.');
    return {...(context||{}),propagation_guidance:data};
};

const liveContextBeforeExam=liveContextFromPlan;
liveContextFromPlan=async function(plan,text){const context=await liveContextBeforeExam(plan,text);if(!pendingExamExplanation)return context;const examQuestion={...pendingExamExplanation};delete examQuestion.figure_url;delete examQuestion.figures_only;pendingExamExplanation=null;return {...(context||{}),exam_question:examQuestion}};

